// Detect file type from binary data or body metadata
// v2.0 FIX by Claude Code 28/02/2026: RENAME binary key to 'file' for Extract PDF Text compatibility
const item = $input.first();
const binary = item.binary;
const body = item.json.body || {};

let fileName = 'archivo_desconocido';
let hasBinary = false;
let binaryKey = null;

// Check binary data first (from multipart upload)
if (binary) {
  binaryKey = Object.keys(binary)[0];
  if (binaryKey) {
    fileName = binary[binaryKey].fileName || fileName;
    hasBinary = true;
  }
}

// Fallback: check body for file metadata
if (fileName === 'archivo_desconocido') {
  if (body.file && body.file.name) fileName = body.file.name;
  else if (body.fileName) fileName = body.fileName;
}

const ext = fileName !== 'archivo_desconocido' ? fileName.split('.').pop().toLowerCase() : '';
const isPdf = ext === 'pdf';
const isImage = ['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'tiff'].includes(ext);
const isDocument = ['pdf', 'doc', 'docx', 'txt', 'csv'].includes(ext);

let fileType = 'unknown';
if (isPdf) fileType = 'pdf';
else if (isImage) fileType = 'image';
else if (isDocument) fileType = 'document';

// If we have binary but couldn't detect from filename, check mimeType
if (fileType === 'unknown' && hasBinary && binaryKey) {
  const mime = (binary[binaryKey].mimeType || '').toLowerCase();
  if (mime.includes('pdf')) { fileType = 'pdf'; }
  else if (mime.startsWith('image/')) fileType = 'image';
  else if (mime.includes('text') || mime.includes('csv')) fileType = 'document';
}

const result = {
  json: {
    ...item.json,
    chatInput: body.text || 'Por favor analiza el archivo recibido.',
    _fileType: fileType,
    _fileName: fileName,
    _fileExt: ext || 'unknown',
    _hasBinary: hasBinary
  }
};

// CRITICAL FIX: Normalize binary key to 'file' so Extract PDF Text can find it.
if (binary && binaryKey) {
  result.binary = {};
  result.binary.file = binary[binaryKey];
  if (binaryKey !== 'file') {
    result.binary.data = binary[binaryKey];
  }
} else if (binary) {
  result.binary = binary;
}

return [result];

// Format Extracted PDF — v1.9 FIX SESSION PROPAGATION
const item = $input.first();
const pages = item.json.text || '';
let extractedText = '';
if (Array.isArray(pages)) extractedText = pages.join('\n\n');
else if (typeof pages === 'string') extractedText = pages;

const fileType = $('Code: Detect File Type').first().json;
const body = fileType.body || {};

return [{ json: {
  _extractedText: extractedText || 'No se pudo extraer texto del PDF.',
  _fileName: fileType._fileName || body._fileName || 'documento.pdf',
  chatInput: body.text || fileType.chatInput || '',
  visitorId: body.visitorId || fileType.visitorId || '',
  sessionId: body.sessionId || fileType.sessionId || '',
  clientId: body.clientId || fileType.clientId || '',
  lang: body.lang || fileType.lang || 'es'
}, binary: item.binary }];

// Format File Extraction - v4.0 IMPROVED CLASSIFICATION
const raw = $input.first().json;
const geminiOutput = raw.text || raw.output || '';
const fileCtx = $('Code: Detect File Type').first().json;
const body = fileCtx.body || {};
const visitorId = body.visitorId || fileCtx.visitorId || '';
const sessionId = body.sessionId || fileCtx.sessionId || '';
const clientId = body.clientId || fileCtx.clientId || '';
const chatInput = body.text || fileCtx.chatInput || '';
const lang = body.lang || fileCtx.lang || 'es';

let audit = { isValidReceipt: false, isLegalDocument: false, documentType: 'irrelevant' };
try {
  let clean = geminiOutput.trim();
  if (clean.includes('```json')) { const m = clean.match(/```json\s*([\s\S]*?)\s*```/); if (m) clean = m[1].trim(); }
  if (clean.startsWith('{')) { audit = JSON.parse(clean); }
} catch(e) {
  const lower = geminiOutput.toLowerCase();
  if (lower.includes('legal') || lower.includes('expediente') || lower.includes('contrato') || lower.includes('multa') || lower.includes('juzgado') || lower.includes('notificacion')) {
    audit = { isValidReceipt: false, isLegalDocument: true, documentType: 'legal_document', documentAnalysis: geminiOutput, documentSummary: geminiOutput.substring(0, 200) };
  } else {
    audit = { isValidReceipt: false, isLegalDocument: false, documentType: 'irrelevant', text: geminiOutput };
  }
}

const isReceipt = audit.isValidReceipt === true && audit.documentType === 'payment_receipt';
const isLegalDocument = audit.isLegalDocument === true || audit.documentType === 'legal_document';

let resultChatInput = '';
if (isReceipt) {
  resultChatInput = '[COMPROBANTE_VALIDO]\nMonto: ' + (audit.amount ? '$' + audit.amount : 'No detectado') +
    '\nN Operacion: ' + (audit.operation_id || 'No detectado') +
    '\nFecha: ' + (audit.transaction_date || 'No detectada') + ' ' + (audit.transaction_time || '') +
    '\nRemitente: ' + (audit.sender_name || 'No detectado') +
    '\nDestinatario: ' + (audit.recipient_name || 'No detectado');
} else if (isLegalDocument) {
  resultChatInput = '[DOCUMENTO_LEGAL]\nEl prospecto envio un documento para explicar su situacion.\nAnalisis del documento adjunto:\n' +
    (audit.documentAnalysis || audit.text || geminiOutput).substring(0, 2000) +
    (audit.documentSummary ? '\nResumen: ' + audit.documentSummary : '') +
    (audit.legalAreas ? '\nAreas legales: ' + audit.legalAreas.join(', ') : '') +
    '\n\nMensaje del prospecto: ' + (chatInput || 'Analiza este documento');
} else {
  resultChatInput = '[ARCHIVO_NO_RELEVANTE]\n' + (audit.text || geminiOutput).substring(0, 1000) +
    '\n\nMensaje del prospecto: ' + (chatInput || '');
}

const geminiText = audit.documentAnalysis || audit.text || geminiOutput.substring(0, 1500);

return [{ json: {
  chatInput: resultChatInput,
  visitorId, sessionId, clientId, lang,
  isReceipt,
  isLegalDocument,
  documentType: audit.documentType || (isReceipt ? 'payment_receipt' : isLegalDocument ? 'legal_document' : 'irrelevant'),
  documentSummary: audit.documentSummary || null,
  legalAreas: audit.legalAreas || null,
  receiptAmount: isReceipt ? (audit.amount || null) : null,
  receiptOperationId: isReceipt ? (audit.operation_id || null) : null,
  receiptDate: isReceipt ? (audit.transaction_date || null) : null,
  receiptTime: isReceipt ? (audit.transaction_time || null) : null,
  receiptSender: isReceipt ? (audit.sender_name || null) : null,
  receiptRecipient: isReceipt ? (audit.recipient_name || null) : null,
  geminiAction: audit.action || null,
  geminiSuggestions: audit.suggestions || null,
  geminiText,
  hasFileAnalysis: true
} }];

// ============================================================
// Config: Bot & SaaS (Hardcoded) - v1.2
// Replaces Supabase: Fetch Bot Config + Fetch SaaS Config
// Edit these values directly when config changes
// ============================================================

// ---- BOT CONFIG ----
const botConfig = {
  bot_name: 'Asistente Virtual - Bañuelos Villalba & Asociados',
  welcome_message: '¡Hola! Soy el asistente virtual de Bañuelos Villalba & Asociados. ¿En qué puedo ayudarte?',
  primary_color: '#1a1a2e',
  language: 'es'
};

// ---- SAAS CONFIG ----
const saasConfig = {
  calendar_id: '86b158a9564f8d1ac7d4bf304decb80b992450653928999bfcc5edec3c82aabc@group.calendar.google.com',
  payment_link: '',
  consultation_price: '500',
  notification_email: '',
  whatsapp_number: '',
  phone_number: ''
};

// ---- COUNT MESSAGES (from Postgres chat memory) ----
let msgCount = 0;
try {
  // We still use Supabase Postgres for chat history counting
  const h = $('Supabase: Count Messages').first().json.headers;
  if (h && h['content-range']) {
    const m = h['content-range'].match(/\/(\d+)/);
    if (m) msgCount = parseInt(m[1], 10);
  }
} catch(e) {}

return [{
  json: {
    botConfig,
    saasConfig,
    msgCount
  }
}];

// ============================================================
// Code: Inject Lead Context - v8.0 GOOGLE SHEETS + SIMPLIFIED LEADS
// Reads from Google Sheets instead of Supabase for lead data
// Only collects: nombre_completo + whatsapp
// ============================================================
const session = $('Set Session ID').first().json;
const clientId = session.clientId || '';
const visitorId = session.visitorId || session.sessionId || '00000000-0000-0000-0000-000000000000';
let chatInput = session.chatInput || '';
const lang = session.lang || 'es';

if (!chatInput) {
  try {
    const fileData = $('Format File Extraction').first().json;
    chatInput = fileData.chatInput || '';
  } catch(e) {}
}

// Read lead from Google Sheets result
let lead = {};
try {
  const d = $('Google Sheets: Read Lead').first().json;
  // Google Sheets returns rows as flat objects - check if we got a valid row
  if (d && (d.nombre_completo || d.whatsapp || d.visitor_id)) {
    lead = d;
  }
} catch(e) {}

// Read hardcoded configs
let botConfig = {};
let saasConfig = {};
let msgCount = 0;
try {
  const cfg = $('Config: Bot & SaaS').first().json;
  botConfig = cfg.botConfig || {};
  saasConfig = cfg.saasConfig || {};
  msgCount = cfg.msgCount || 0;
} catch(e) {}

const calendarId = saasConfig.calendar_id || '';
const paymentLink = saasConfig.payment_link || '';
const consultationPrice = saasConfig.consultation_price || '';
const lawyerConfirmed = lead.lawyer_confirmed_payment === 'true' || lead.lawyer_confirmed_payment === true;
const isPaid = (lead.status === 'paid' || lead.status === 'scheduled') && lawyerConfirmed;

// Build enriched context
let enrichedInput = chatInput;
const parts = [];

// Lead data — SIMPLIFIED: only nombre + whatsapp
if (lead.nombre_completo) parts.push('Nombre: ' + lead.nombre_completo);
else parts.push('Nombre: NO PROPORCIONADO');
if (lead.whatsapp) parts.push('WhatsApp: ' + lead.whatsapp);
else parts.push('WhatsApp: NO PROPORCIONADO');

parts.push('Estado: ' + (lead.status || 'new'));
parts.push('PagoConfirmadoPorAbogado: ' + (lawyerConfirmed ? 'SI' : 'NO'));

if (lead.scheduled_date) parts.push('Cita: ' + lead.scheduled_date + ' ' + (lead.scheduled_time || ''));
if (lead.ai_summary) parts.push('Resumen previo: ' + String(lead.ai_summary).substring(0, 800));

// Data collection hints — SIMPLIFIED
const missingData = [];
if (!lead.nombre_completo) missingData.push('nombre completo');
if (!lead.whatsapp) missingData.push('número de WhatsApp');

if (missingData.length > 0) {
  parts.push('DATOS_FALTANTES: ' + missingData.join(', '));
  if (msgCount >= 2) parts.push('INSTRUCCION: Pide los datos faltantes (' + missingData.join(', ') + ') DE UNA SOLA VEZ en tu próximo mensaje.');
}

// Payment context for AI
if (paymentLink) parts.push('PAYMENT_LINK_DISPONIBLE: ' + paymentLink);
if (consultationPrice) parts.push('PRECIO_CONSULTA: $' + consultationPrice + ' MXN');

if (parts.length > 0) {
  enrichedInput = '[CONTEXTO - msgs: ' + msgCount + '\n' + parts.join('\n') + ']\n\n' + chatInput;
} else {
  enrichedInput = '[NUEVO - msgs: ' + msgCount + ']\n\n' + chatInput;
}

return [{
  json: {
    sessionId: session.sessionId || visitorId,
    chatInput: enrichedInput,
    raw_chat_input: chatInput,
    current_ai_summary: lead.ai_summary || '',
    clientId,
    visitorId,
    lang,
    calendarId,
    bot_name: botConfig.bot_name || 'Asistente Virtual',
    lead_name: lead.nombre_completo || '',
    lead_whatsapp: lead.whatsapp || '',
    lead_status: lead.status || 'new',
    lead_id: lead.row_number || '',
    is_paid: isPaid,
    lawyer_confirmed: lawyerConfirmed,
    msg_count: msgCount,
    payment_link: paymentLink,
    consultation_price: consultationPrice,
    notification_email: saasConfig.notification_email || '',
    whatsapp_number: saasConfig.whatsapp_number || '',
    phone_number: saasConfig.phone_number || ''
  }
}];

// ============================================================
// Formatear Respuesta - v12.0 SIMPLIFIED LEADS (nombre + whatsapp)
// NEW: Supports Google Sheets data model, no email/phone fields
// ============================================================
const ctx = $('Code: Inject Lead Context').first().json;
const raw = $input.first().json.output || $input.first().json.text || '';
let text = '', suggestions = [], action = 'general_inquiry', ld = {}, llmSummary = '';

try {
  let c = raw.trim();
  if (c.includes('```json')) { const m = c.match(/```json\s*([\s\S]*?)\s*```/); if (m) c = m[1].trim(); }
  if (c.startsWith('{')) {
    const p = JSON.parse(c);
    text = p.text || '';
    suggestions = p.suggestions || [];
    action = p.action || 'general_inquiry';
    ld = p.lead_data || {};
    llmSummary = p.ai_summary || '';
  } else { text = c; }
} catch(e) { text = raw; }

let intention = action;
let isReceipt = false, isLegalDocument = false, documentType = '';
let rAmt = null, rOp = null, rDate = null, rSender = null, rRecipient = null;
let hasFileAnalysis = false, geminiText = '', geminiSuggestions = null, documentSummary = null;

try {
  const f = $('Format File Extraction').first().json;
  isReceipt = f.isReceipt || false;
  isLegalDocument = f.isLegalDocument || false;
  documentType = f.documentType || '';
  documentSummary = f.documentSummary || null;
  rAmt = f.receiptAmount; rOp = f.receiptOperationId;
  rDate = f.receiptDate; rSender = f.receiptSender; rRecipient = f.receiptRecipient;
  hasFileAnalysis = f.hasFileAnalysis || false;
  geminiText = f.geminiText || '';
  geminiSuggestions = f.geminiSuggestions || null;
} catch(e) {}

// SIMPLIFIED: Only check nombre_completo + whatsapp
const hasName = !!(ld.nombre_completo || ctx.lead_name);
const hasWhatsapp = !!(ld.whatsapp || ctx.lead_whatsapp);
const hasAllData = hasName && hasWhatsapp;
const isPaid = ctx.is_paid === true;
const lawyerConfirmed = ctx.lawyer_confirmed === true;

const justProvidedData = hasAllData && (
  (ld.nombre_completo && !ctx.lead_name) || (ld.whatsapp && !ctx.lead_whatsapp)
);

const hasPaymentLink = !!(ctx.payment_link && ctx.payment_link.length > 5);
const hasPrice = !!(ctx.consultation_price && ctx.consultation_price !== '' && ctx.consultation_price !== '0');

let showPaymentCard = false;

// Detect EXPLICIT payment/scheduling intent
const rawInput = (ctx.raw_chat_input || '').toLowerCase();
const userExplicitlyWantsPayment = (
  rawInput.includes('quiero agendar') ||
  rawInput.includes('quiero pagar') ||
  rawInput.includes('agendar consulta') ||
  rawInput.includes('agendar turno') ||
  rawInput.includes('agendar cita') ||
  rawInput.includes('como pago') ||
  rawInput.includes('cómo pago') ||
  rawInput.includes('link de pago') ||
  rawInput.includes('cuanto cuesta') ||
  rawInput.includes('cuánto cuesta') ||
  rawInput.includes('precio de la consulta') ||
  rawInput.includes('quiero contratar') ||
  rawInput.includes('ya pagué') ||
  rawInput.includes('ya transferí')
);

// --- 1. DATA GATE: Enforce data collection before payment/scheduling ---
if (!hasAllData && (intention === 'schedule_appointment' || intention === 'payment_inquiry')) {
    intention = 'general_inquiry';
    text = 'Para poder avanzar con tu solicitud, necesito que me indiques tu **nombre completo** y **número de WhatsApp** en un solo mensaje. Una vez que me los pases, continuamos.';
    suggestions = ['Dar mis datos', 'Tengo una consulta'];
}

// --- 2. PAYMENT FLOW: Only on EXPLICIT payment/scheduling intent ---
else if (hasAllData && !isPaid && !isReceipt && (
    intention === 'payment_inquiry' ||
    intention === 'schedule_appointment' ||
    (justProvidedData && userExplicitlyWantsPayment)
)) {
    intention = 'payment_inquiry';
    showPaymentCard = true;
    const price = hasPrice ? ctx.consultation_price : 'a consultar';
    const link = hasPaymentLink ? ctx.payment_link : '';

    text = '¡Listo! Para confirmar tu consulta, el siguiente paso es completar el pago.';
    if (!link) {
      text += '\n\nEl costo de la consulta es de **$' + price + ' MXN**. Contactanos para coordinar la forma de pago.';
    }
    text += '\n\n❗ **Importante:** Una vez que hagas la transferencia, subí el comprobante como imagen o PDF directamente a este chat. No aceptamos confirmación por texto.';

    suggestions = link ? ['❓ ¿Cómo funciona?', '📎 Ya pagué, subir comprobante'] : ['¿Cómo pago?', 'Tengo una duda'];
}

// --- 3. GENERAL INQUIRY: ALWAYS passes clean ---

// --- 4. SCRUBBING & ANTI-HALLUCINATION ---
if (!hasAllData && text) {
  const price = ctx.consultation_price;
  const priceRegex = /\$[\d.,]+/g;
  let hasPriceInText = !!text.match(priceRegex);
  if (price && !hasPriceInText) {
    const priceStr = String(price);
    if (text.includes(priceStr) && price > 0) hasPriceInText = true;
  }
  if (hasPriceInText || (ctx.payment_link && text.includes(ctx.payment_link))) {
    text = text.replace(priceRegex, '[precio disponible al completar tus datos]');
    if (price) {
      const ps = String(price);
      const escapedPrice = ps.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      text = text.replace(new RegExp('\\*{0,2}' + escapedPrice + '\\*{0,2}', 'g'), '[precio disponible al completar tus datos]');
    }
    const linkRegex = /https?:\/\/[^\s)]+/g;
    text = text.replace(linkRegex, '[link disponible al completar tus datos]');
  }
}

if (!lawyerConfirmed && text) {
  text = text.replace(/pago confirmado/gi, 'pago en proceso de verificación');
  text = text.replace(/tu pago fue confirmado/gi, 'tu pago está en proceso de verificación');
  text = text.replace(/ya está confirmado/gi, 'está en proceso de verificación');
}
if (!lawyerConfirmed && llmSummary) {
  llmSummary = llmSummary.replace(/[Pp]ago confirmado/g, 'Pago pendiente de confirmación por abogado');
}

// --- 5. Parse date/time ---
let leadDate = ld.date || '';
let leadTime = ld.time || '';
if (intention === 'schedule_appointment' && isPaid) {
  if (!leadDate || !leadTime) {
    if (!leadDate) {
      const dateMatch = rawInput.match(/(\d{1,2})\s*(?:de\s*)?(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)/i);
      if (dateMatch) {
        const months = {enero:'01',febrero:'02',marzo:'03',abril:'04',mayo:'05',junio:'06',julio:'07',agosto:'08',septiembre:'09',octubre:'10',noviembre:'11',diciembre:'12'};
        leadDate = '2026-' + months[dateMatch[2].toLowerCase()] + '-' + dateMatch[1].padStart(2,'0');
      }
    }
    if (!leadTime) {
      const timeMatch = rawInput.match(/(\d{1,2})[:.]?(\d{2})?\s*(?:hs|hrs|horas|h)?/i);
      if (timeMatch) { leadTime = timeMatch[1].padStart(2,'0') + ':' + (timeMatch[2] || '00'); }
    }
  }
  if (leadDate && leadTime) { action = 'schedule_processing'; }
}

// --- 6. RECEIPT HANDLING ---
if (isReceipt) {
  if (!hasAllData) {
    text = '¡Recibimos tu comprobante! Antes de procesarlo, necesito tus datos.\n\nPor favor, indicame tu **nombre completo** y **número de WhatsApp** en un solo mensaje.';
    suggestions = ['Dar mis datos', 'Tengo una consulta'];
    intention = 'general_inquiry'; isReceipt = false;
  } else {
    const amtStr = rAmt ? '$' + rAmt + ' MXN' : ''; const opStr = rOp ? ' | Op: ' + rOp : '';
    text = '¡Comprobante recibido!\n\nTu comprobante fue recibido correctamente. Nuestro equipo lo verificará y te confirmaremos a la brevedad.\n\nUna vez confirmado el pago, se te habilitará automáticamente la agenda para elegir tu turno.\n\n' + (amtStr ? 'Monto detectado: ' + amtStr + opStr : '');
    suggestions = ['Consultar estado', '¿Cuánto tarda?', 'Tengo otra consulta'];
    intention = 'payment_inquiry';
  }
}
else if (hasFileAnalysis && isLegalDocument) {
  if (!suggestions.length) {
    suggestions = geminiSuggestions || ['Agendar consulta sobre este caso', 'Enviar otro documento', 'Hacer una pregunta'];
  }
  intention = 'general_inquiry';
}
else if (hasFileAnalysis && !isReceipt && !isLegalDocument) {
  if (!text || text.length < 20) {
    text = 'No pudimos identificar el archivo.\n\nPodés enviarnos:\n- **Documentos de tu caso**: multas, notificaciones, contratos\n- **Comprobante de pago**: captura de transferencia o PDF';
  }
  if (!suggestions.length) {
    suggestions = ['Enviar documento', 'Subir comprobante', 'Tengo una consulta'];
  }
  intention = 'general_inquiry';
}

// --- 7. SMART SUGGESTIONS ---
if (!suggestions.length) {
  if (!hasName) {
    suggestions = ['Conocer servicios', 'Tengo un caso', 'Quiero agendar consulta'];
  } else if (!hasAllData) {
    suggestions = ['Enviar documento', 'Consultar servicios', 'Agendar consulta'];
  } else if (isPaid) {
    suggestions = ['Agendar consulta', 'Enviar documento', 'Estado de mi pago'];
  } else {
    suggestions = ['Información de pago', 'Enviar documento', 'Hacer una pregunta'];
  }
}

// --- 8. AI SUMMARY ---
let finalAiSummary = llmSummary || ctx.current_ai_summary || '';
finalAiSummary = finalAiSummary.replace(/\[COMPROBANTE_VALIDO\]\s*/g, '').replace(/\[COMPROBANTE_RECHAZADO\]\s*/g, '').replace(/\[DOCUMENTO_LEGAL\]\s*/g, '').replace(/\[ARCHIVO_NO_RELEVANTE\]\s*/g, '');
if (isReceipt) { finalAiSummary = '[COMPROBANTE_VALIDO] ' + finalAiSummary; }
else if (hasFileAnalysis && isLegalDocument && documentSummary) { finalAiSummary = finalAiSummary.trim() + ' | Doc adjunto: ' + documentSummary; }
if (!hasFileAnalysis) {
  if (ctx.current_ai_summary && ctx.current_ai_summary.includes('[COMPROBANTE_VALIDO]') && !finalAiSummary.includes('[COMPROBANTE_VALIDO]')) {
    finalAiSummary = '[COMPROBANTE_VALIDO] ' + finalAiSummary;
  }
}

return [{ json: {
  text: text || 'Disculpa, no pude procesar tu solicitud. Podés intentar de nuevo.',
  suggestions,
  action,
  intention,
  showPaymentCard,
  confidence: 0.8,
  clientId: ctx.clientId,
  visitorId: ctx.visitorId,
  sessionId: ctx.sessionId,
  leadId: ctx.lead_id,
  leadName: ld.nombre_completo || ctx.lead_name,
  leadWhatsapp: ld.whatsapp || ctx.lead_whatsapp,
  leadDate,
  leadTime,
  leadStatus: ctx.lead_status,
  isPaid,
  lawyerConfirmed,
  isExistingLead: !!ctx.lead_id,
  botName: ctx.bot_name,
  paymentLink: hasAllData ? ctx.payment_link : '',
  consultationPrice: hasAllData ? ctx.consultation_price : 0,
  notificationEmail: ctx.notification_email,
  whatsappNumber: ctx.whatsapp_number,
  phoneNumber: ctx.phone_number,
  calendarId: ctx.calendarId || '',
  isReceipt,
  receiptAmount: rAmt,
  receiptOperationId: rOp,
  receiptDate: rDate,
  receiptSender: rSender,
  receiptRecipient: rRecipient,
  isLegalDocument,
  documentType,
  documentSummary,
  ai_summary: finalAiSummary
} }];

const body = $input.first().json.body || {};
const clientId = body.clientId || '';
const dateStr = body.date;

const timeMin = dateStr ? dateStr + 'T00:00:00-03:00' : new Date().toISOString();
const timeMax = dateStr ? dateStr + 'T23:59:59-03:00' : new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

return [{ json: { clientId, dateStr, timeMin, timeMax, body } }];

const events = $input.first().json.items || [];
const body = $('Fetch Calendar Busy').first().json.body || {};
const dateStr = $('Fetch Calendar Busy').first().json.dateStr;

const workStart = 9;
const workEnd = 18;
const slotDuration = 60;

const busySlots = events
  .filter(e => e.start && (e.start.dateTime || e.start.date))
  .map(e => {
    const start = new Date(e.start.dateTime || e.start.date + 'T00:00:00');
    const end = new Date(e.end?.dateTime || e.end?.date + 'T23:59:00');
    return { start: start.getHours() * 60 + start.getMinutes(), end: end.getHours() * 60 + end.getMinutes(), title: e.summary || 'Ocupado' };
  });

const availableSlots = [];
for (let h = workStart; h < workEnd; h++) {
  const slotStart = h * 60;
  const slotEnd = slotStart + slotDuration;
  const isOccupied = busySlots.some(b => slotStart < b.end && slotEnd > b.start);
  if (!isOccupied) {
    availableSlots.push(`${h.toString().padStart(2, '0')}:00`);
  }
}

let message = '';
if (availableSlots.length === 0) {
  message = dateStr 
    ? `No hay turnos disponibles el ${dateStr}. ¿Querés consultar otro día?`
    : 'No hay turnos disponibles en los próximos 7 días. Por favor contactate directamente.';
} else {
  const slots = availableSlots.join(', ');
  message = dateStr
    ? `Turnos disponibles para el ${dateStr}: ${slots}`
    : `Turnos disponibles próximos días: ${slots}`;
}

return [{ json: {
  success: true,
  availableSlots,
  busySlots: busySlots.map(b => b.title),
  message,
  suggestions: availableSlots.slice(0, 3).map(s => `Turno a las ${s}`).concat(['Ver otro día']),
  action: 'schedule_appointment'
} }];

const body = $input.first().json.body || {};
const metadata = typeof body.metadata === 'string' ? JSON.parse(body.metadata) : (body.metadata || {});

return [{
  json: {
    visitorId: body.visitorId || metadata.visitorId || '',
    clientId: body.clientId || metadata.clientId || '',
    abandonmentData: {
      url: metadata.url || '',
      timestamp: metadata.timestamp || new Date().toISOString(),
      source: metadata.source || 'unknown',
      medium: metadata.medium || 'unknown'
    }
  }
}];

// ============================================================
// [GUARD] - Anti-Spam + Rate Limiting + CORS + Payload Validation
// Recepcionista AI v1.3 [DEV] - NF-08
// MODIFIED: CORS Origin * (Acepta cualquier website)
// ============================================================

const item = $input.first();
const binary = item.binary;
const body = item.json.body || {};
const headers = item.json.headers || {};
const errors = [];

// --- 1. CORS: Permitir cualquier origen (*) ---
const origin = (headers['origin'] || headers['referer'] || '').toLowerCase();
const isOriginAllowed = true;

// --- 2. Validacion de payload obligatorio ---
const clientId = body.clientId || body.client_id || '';
const visitorId = body.visitorId || body.visitor_id || '';
const action = body.action || '';
const text = body.text || '';

if (!clientId) errors.push('Missing clientId');
if (!visitorId) errors.push('Missing visitorId');

// --- 3. Validar accion en whitelist ---
const allowedActions = ['user_message', 'file_upload', 'get_availability', 'user_abandoned_page'];
if (action && !allowedActions.includes(action)) {
  errors.push('Invalid action: ' + action);
}

// --- 4. Validar longitud del texto (max 2000 chars) ---
if (text && text.length > 2000) {
  errors.push('Text exceeds 2000 character limit (' + text.length + ' chars)');
}

// --- 5. Rate Limiting en memoria (por visitor_id) ---
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};

const now = Date.now();
const WINDOW_MS = 60000;
const MAX_PER_VISITOR = 10;
const MAX_PER_IP = 30;

if (!staticData.cleanupCounter) staticData.cleanupCounter = 0;
staticData.cleanupCounter++;
if (staticData.cleanupCounter >= 100) {
  staticData.cleanupCounter = 0;
  for (const key of Object.keys(staticData.rateLimits)) {
    staticData.rateLimits[key] = staticData.rateLimits[key].filter(ts => now - ts < WINDOW_MS);
    if (staticData.rateLimits[key].length === 0) delete staticData.rateLimits[key];
  }
}

let rateLimited = false;
if (visitorId) {
  const vKey = 'v_' + visitorId;
  if (!staticData.rateLimits[vKey]) staticData.rateLimits[vKey] = [];
  staticData.rateLimits[vKey] = staticData.rateLimits[vKey].filter(ts => now - ts < WINDOW_MS);
  if (staticData.rateLimits[vKey].length >= MAX_PER_VISITOR) {
    rateLimited = true;
    errors.push('Rate limit exceeded: ' + MAX_PER_VISITOR + ' msgs/min per visitor');
  } else {
    staticData.rateLimits[vKey].push(now);
  }
}

const clientIp = headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown';
if (clientIp !== 'unknown') {
  const ipKey = 'ip_' + clientIp.split(',')[0].trim();
  if (!staticData.rateLimits[ipKey]) staticData.rateLimits[ipKey] = [];
  staticData.rateLimits[ipKey] = staticData.rateLimits[ipKey].filter(ts => now - ts < WINDOW_MS);
  if (staticData.rateLimits[ipKey].length >= MAX_PER_IP) {
    rateLimited = true;
    errors.push('Rate limit exceeded: ' + MAX_PER_IP + ' reqs/min per IP');
  } else {
    staticData.rateLimits[ipKey].push(now);
  }
}

const passed = errors.length === 0;
const statusCode = rateLimited ? 429 : (passed ? 200 : 400);

const result = {
  json: {
    body,
    headers,
    _guard: { passed, statusCode, errors, rateLimited, origin: origin || 'none', clientIp, timestamp: new Date().toISOString() }
  }
};
if (binary && Object.keys(binary).length > 0) {
  result.binary = binary;
}
return [result];
